from pathlib import Path
import json,numpy as np
R=Path(__file__).resolve().parents[1];A=R/'artifacts/bilin18_tensor_decomposition';stem='bilin18_l17_compiled_finite_source_law';j=json.loads((A/f'{stem}.json').read_text());z=np.load(A/f'{stem}_rows.npz');e=z['errors'];d=z['effects'];assert e.shape==(8,2,9,24,128,2) and np.isfinite(e).all() and all(j['numerical_gates'].values());rec=1-e.sum((3,4))/d.sum((1,2))[:,None,None,:];prior=np.load(A/'bilin18_l17_compact_amplitude_response_rows.npz');ee=np.concatenate([e[7,...,1],prior['errors'][7,0,...,1][None]],axis=0);dd=d[7,...,1]
def contrast(r,sp):return np.array([r[0,0]-r[2,0],(r[0,1+sp]-r[2,1+sp]).mean(),r[1,0]-r[0,0],(r[1,1+sp]-r[0,1+sp]).mean()])
pooled=1-ee.sum((2,3))/dd.sum();pt=contrast(pooled,np.arange(8));assert np.allclose(pooled[:2],rec[7,...,1]);rng=np.random.default_rng(j['config']['bootstrap_seed']);boot=[]
for _ in range(j['config']['bootstrap_samples']):
 pairs=rng.integers(0,12,12);sw=np.bincount(np.r_[pairs,12+pairs],minlength=24);dw=np.bincount(rng.integers(0,128,128),minlength=128);sp=rng.integers(0,8,8);rr=1-np.einsum('mbsi,s,i->mb',ee,sw,dw,optimize=True)/np.einsum('si,s,i->',dd,sw,dw,optimize=True);boot.append(contrast(rr,sp))
boot=np.array(boot);radius=np.quantile(abs(boot-pt).max(1),.95);ci=np.stack([pt-radius,pt+radius],1);thresholds=np.array([.005,.005,-.02,-.02]);j.update(primary_names=['finite_minus_first_learned','finite_minus_first_random','compact_minus_dense_finite_learned','compact_minus_dense_finite_random'],primary=pt.tolist(),primary_joint4_ci95=ci.tolist(),primary_thresholds=thresholds.tolist(),primary_gates=(ci[:,0]>thresholds).tolist(),finite_KL_recovery=rec[...,1].tolist(),Fisher_recovery=rec[...,0].tolist(),direct_finite_KL_recovery=(1-z['direct_errors'][...,1].sum((2,3))/d[...,1].sum((1,2))[:,None]).tolist());np.savez_compressed(A/f'{stem}_bootstrap.npz',primary=boot);(A/f'{stem}.json').write_text(json.dumps(j,indent=2)+'\n');print('primary',pt,'CI',ci,'gates',j['primary_gates'])
for amp,r,dr in zip(j['config']['amplitudes'],rec[...,1],j['direct_finite_KL_recovery']):print(amp,'learned',r[:,0],'random',r[:,1:].mean(1),'direct',dr)
